// Shared send limiter for proactive lead messages.
//
// Every worker on this machine asks reserve() before sending and calls
// release() if the provider rejects the message. History lives in
// STATE_DIR/leads/<sha256(userId)>.json, one file per lead, so it survives a
// worker restart and is visible to all workers.
//
// Concurrency: each lead has a lock directory (mkdir is atomic on a local
// filesystem). Read-check-write runs while holding that lock, so two workers
// cannot both take the last slot for the same lead.

import { createHash, randomUUID } from 'node:crypto';
import { mkdir, open, readFile, rename, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const LOCK_STALE_MS = 10_000; // a holder works for milliseconds; older locks belong to a crashed worker
const LOCK_RETRY_MS = 5;
const KEY_PATTERN = /^[0-9a-f]{64}$/;

// Counts a reservation as a message the lead may have received:
// - a reservation counts from the moment it is granted, even if the send is still in flight
//   or the worker crashed before sending (the message may have gone out anyway);
// - release() removes the reservation, because the provider rejected it and the lead got nothing.
// Blocked attempts are never recorded: the lead did not receive them.
//
// Window: sliding. A send counts for windowHours after it was granted. Fixed
// calendar windows would allow a burst of 2 × maxPerWindow around a boundary.
// Gap: minGapMinutes must pass since the most recent counted send.
//
// Reason codes (one per limit):
//   max_per_window_exceeded - maxPerWindow sends already fall inside the window
//   min_gap_not_elapsed     - the last send is less than minGapMinutes ago

export async function reserve(request, now) {
  const req = validateRequest(request);
  const at = validateNow(now);
  const stateDir = requireStateDir();
  const key = hashUser(req.userId);
  const windowMs = req.windowHours * HOUR_MS;
  const gapMs = req.minGapMinutes * MINUTE_MS;

  return withLead(stateDir, key, async (file) => {
    const state = await loadState(file);
    // Keep history as long as the longest window or gap any call has used,
    // so the check below still sees every send that matters.
    state.keepMs = Math.max(state.keepMs ?? 0, windowMs, gapMs);
    state.userId = req.userId;
    state.reservations = state.reservations.filter((r) => r.at > at - state.keepMs);

    const inWindow = state.reservations.filter((r) => r.at > at - windowMs);
    if (inWindow.length >= req.maxPerWindow) {
      return { allowed: false, reason: 'max_per_window_exceeded', reservationId: null };
    }

    const last = state.reservations.reduce((max, r) => Math.max(max, r.at), -Infinity);
    if (at - last < gapMs) {
      return { allowed: false, reason: 'min_gap_not_elapsed', reservationId: null };
    }

    // Reservation id = <lead key>.<uuid>, so release() can find the file without a userId.
    const reservationId = `${key}.${randomUUID()}`;
    state.reservations.push({ id: reservationId, at: at.getTime() });
    await saveState(file, state);
    return { allowed: true, reason: null, reservationId };
  });
}

export async function release(reservationId) {
  if (typeof reservationId !== 'string') {
    throw new TypeError('reservationId must be a string');
  }
  const dot = reservationId.indexOf('.');
  const key = reservationId.slice(0, dot);
  if (dot < 0 || !KEY_PATTERN.test(key)) {
    // Not an id this module issued. Nothing to give back.
    return;
  }
  const stateDir = requireStateDir();

  await withLead(stateDir, key, async (file) => {
    const state = await loadState(file);
    const remaining = state.reservations.filter((r) => r.id !== reservationId);
    if (remaining.length === state.reservations.length) return; // already released or pruned
    state.reservations = remaining;
    await saveState(file, state);
  });
}

// ---------- helpers ----------

function requireStateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR environment variable is not set');
  return dir;
}

function hashUser(userId) {
  return createHash('sha256').update(userId).digest('hex');
}

function validateRequest(request) {
  if (!request || typeof request !== 'object') {
    throw new TypeError('request must be an object');
  }
  const { userId, maxPerWindow, windowHours, minGapMinutes } = request;
  if (typeof userId !== 'string' || userId.length === 0) {
    throw new TypeError('userId must be a non-empty string');
  }
  if (!Number.isInteger(maxPerWindow) || maxPerWindow < 1) {
    throw new TypeError('maxPerWindow must be an integer >= 1');
  }
  if (!Number.isFinite(windowHours) || windowHours <= 0) {
    throw new TypeError('windowHours must be a number > 0');
  }
  if (!Number.isFinite(minGapMinutes) || minGapMinutes < 0) {
    throw new TypeError('minGapMinutes must be a number >= 0');
  }
  return { userId, maxPerWindow, windowHours, minGapMinutes };
}

function validateNow(now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }
  return now;
}

// Runs fn(file) while holding the lock for one lead.
async function withLead(stateDir, key, fn) {
  const leadsDir = join(stateDir, 'leads');
  await mkdir(leadsDir, { recursive: true });
  const lockPath = join(leadsDir, `${key}.lock`);
  await acquire(lockPath);
  try {
    return await fn(join(leadsDir, `${key}.json`));
  } finally {
    await rm(lockPath, { recursive: true, force: true });
  }
}

async function acquire(lockPath) {
  for (;;) {
    try {
      await mkdir(lockPath);
      return;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
    }
    try {
      const { mtimeMs } = await stat(lockPath);
      if (Date.now() - mtimeMs > LOCK_STALE_MS) {
        await rm(lockPath, { recursive: true, force: true });
        continue;
      }
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      continue; // holder released between our mkdir and stat
    }
    await sleep(LOCK_RETRY_MS + Math.random() * LOCK_RETRY_MS);
  }
}

async function loadState(file) {
  let raw;
  try {
    raw = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return { reservations: [] };
    throw err;
  }
  // A corrupt file throws instead of resetting: a reset would silently lift every limit.
  return JSON.parse(raw);
}

// Write to a temp file, fsync, then rename, so a crash never leaves a half-written history.
async function saveState(file, state) {
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  const handle = await open(tmp, 'w');
  try {
    await handle.writeFile(JSON.stringify(state));
    await handle.sync();
  } finally {
    await handle.close();
  }
  await rename(tmp, file);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { mkdtemp, readdir, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import assert from 'node:assert/strict';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g4-1/bot.mjs';
const run = promisify(execFile);
const HOUR = 3_600_000;
const MIN = 60_000;

const stateDir = await mkdtemp(join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = stateDir;
const { reserve, release } = await import(BOT);

const T0 = new Date('2026-10-22T10:00:00Z');
const at = (ms) => new Date(T0.getTime() + ms);
const req = (over = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 90, ...over });

const results = [];
async function test(name, fn) {
  try { await fn(); results.push(['PASS', name]); }
  catch (e) { results.push(['FAIL', name, e.message]); }
}

// Child process: reserve or release using the same STATE_DIR, as another worker would.
async function child(code, args) {
  const { stdout } = await run(process.execPath, ['--input-type=module', '-e', code, BOT, ...args], {
    env: { ...process.env, STATE_DIR: stateDir },
  });
  return JSON.parse(stdout);
}
const CHILD_RESERVE = `
  const [bot, userId, max, gap, ms] = process.argv.slice(1);
  const { reserve } = await import(bot);
  const r = await reserve({ userId, maxPerWindow: +max, windowHours: 24, minGapMinutes: +gap }, new Date(${T0.getTime()} + +ms));
  console.log(JSON.stringify(r));`;
const CHILD_RELEASE = `
  const [bot, id] = process.argv.slice(1);
  const { release } = await import(bot);
  await release(id);
  console.log(JSON.stringify({ ok: true }));`;

await test('cap: 4th send in window is denied with max_per_window_exceeded', async () => {
  const u = 'cap_user';
  for (let i = 0; i < 3; i++) {
    const r = await reserve(req({ userId: u, minGapMinutes: 0 }), at(i * 1000));
    assert.equal(r.allowed, true);
    assert.equal(typeof r.reservationId, 'string');
  }
  const r = await reserve(req({ userId: u, minGapMinutes: 0 }), at(5000));
  assert.deepEqual(r, { allowed: false, reason: 'max_per_window_exceeded', reservationId: null });
});

await test('gap: send too soon after last is denied with min_gap_not_elapsed; allowed after gap', async () => {
  const u = 'gap_user';
  assert.equal((await reserve(req({ userId: u }), at(0))).allowed, true);
  const early = await reserve(req({ userId: u }), at(30 * MIN));
  assert.deepEqual(early, { allowed: false, reason: 'min_gap_not_elapsed', reservationId: null });
  assert.equal((await reserve(req({ userId: u }), at(90 * MIN))).allowed, true);
});

await test('sliding window: old send drops out exactly after windowHours', async () => {
  const u = 'slide_user';
  const r2 = req({ userId: u, maxPerWindow: 2, minGapMinutes: 0 });
  assert.equal((await reserve(r2, at(0))).allowed, true);
  assert.equal((await reserve(r2, at(10 * HOUR))).allowed, true);
  assert.equal((await reserve(r2, at(23 * HOUR))).reason, 'max_per_window_exceeded');
  assert.equal((await reserve(r2, at(24 * HOUR + 1))).allowed, true); // first send (t=0) has aged out
});

await test('per-call limits: a call with a different cap is honored', async () => {
  const u = 'percall_user';
  assert.equal((await reserve(req({ userId: u, maxPerWindow: 1, minGapMinutes: 0 }), at(0))).allowed, true);
  assert.equal((await reserve(req({ userId: u, maxPerWindow: 5, minGapMinutes: 0 }), at(1000))).allowed, true);
});

await test('release frees the slot and the gap; second release is a no-op', async () => {
  const u = 'release_user';
  const a = await reserve(req({ userId: u, maxPerWindow: 1 }), at(0));
  assert.equal((await reserve(req({ userId: u, maxPerWindow: 1 }), at(MIN))).allowed, false);
  await release(a.reservationId);
  await release(a.reservationId);
  await release('not-a-real-id');
  const b = await reserve(req({ userId: u, maxPerWindow: 1 }), at(2 * MIN));
  assert.equal(b.allowed, true, JSON.stringify(b));
});

await test('blocked attempts are not recorded (they do not consume slots)', async () => {
  const u = 'blocked_user';
  const r1 = req({ userId: u, maxPerWindow: 1, minGapMinutes: 60 });
  assert.equal((await reserve(r1, at(0))).allowed, true);
  for (let i = 1; i <= 5; i++) assert.equal((await reserve(r1, at(i * MIN))).allowed, false);
  await assert.rejects(() => reserve(req({ userId: '' }), at(0)), TypeError);
});

await test('cross-process: history written by one process is seen by another', async () => {
  const u = 'xproc_user';
  const r = req({ userId: u, maxPerWindow: 1 });
  const first = await child(CHILD_RESERVE, [u, '1', '0', '0']);
  assert.equal(first.allowed, true);
  const second = await reserve(r, at(1000));
  assert.equal(second.reason, 'max_per_window_exceeded');
});

await test('cross-process release: slot reserved by one process is freed by another', async () => {
  const u = 'xrel_user';
  const r = req({ userId: u, maxPerWindow: 1 });
  const held = await child(CHILD_RESERVE, [u, '1', '0', '0']);
  await child(CHILD_RELEASE, [held.reservationId]);
  assert.equal((await reserve(r, at(1000))).allowed, true);
});

await test('concurrency: 12 processes race for the last slots of one lead, exactly maxPerWindow win', async () => {
  const u = 'race_user';
  const outs = await Promise.all(Array.from({ length: 12 }, () => child(CHILD_RESERVE, [u, '3', '0', '0'])));
  const allowed = outs.filter((o) => o.allowed);
  assert.equal(allowed.length, 3, JSON.stringify(outs.map((o) => o.reason)));
  assert.equal(new Set(allowed.map((o) => o.reservationId)).size, 3);
  assert.equal(outs.filter((o) => !o.allowed).every((o) => o.reason === 'max_per_window_exceeded'), true);
});

await test('concurrency: parallel reserves on different leads do not block each other', async () => {
  const outs = await Promise.all(Array.from({ length: 8 }, (_, i) => child(CHILD_RESERVE, [`par_${i}`, '1', '0', '0'])));
  assert.equal(outs.every((o) => o.allowed), true);
});

await test('stale lock from a crashed worker is recovered', async () => {
  const u = 'stale_user';
  const r = await reserve(req({ userId: u }), at(0)); // creates leads/ dir
  assert.equal(r.allowed, true);
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update(u).digest('hex');
  const lock = join(stateDir, 'leads', `${key}.lock`);
  await (await import('node:fs/promises')).mkdir(lock);
  const old = new Date(Date.now() - 60_000);
  await (await import('node:fs/promises')).utimes(lock, old, old);
  const out = await reserve(req({ userId: u }), at(5 * HOUR));
  assert.equal(out.allowed, true);
});

await test('corrupt history file throws instead of silently lifting limits', async () => {
  const u = 'corrupt_user';
  await reserve(req({ userId: u }), at(0));
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update(u).digest('hex');
  await writeFile(join(stateDir, 'leads', `${key}.json`), '{not json');
  await assert.rejects(() => reserve(req({ userId: u }), at(5 * HOUR)));
});

await test('missing STATE_DIR throws', async () => {
  const saved = process.env.STATE_DIR;
  delete process.env.STATE_DIR;
  await assert.rejects(() => reserve(req(), at(0)), /STATE_DIR/);
  process.env.STATE_DIR = saved;
});

for (const [status, name, msg] of results) console.log(status, name, msg ? `\n    ${msg}` : '');
const failed = results.filter((r) => r[0] === 'FAIL').length;
console.log(`\n${results.length - failed}/${results.length} passed`);
const leftoverLocks = (await readdir(join(stateDir, 'leads'))).filter((f) => f.endsWith('.lock'));
console.log('leftover lock dirs:', leftoverLocks.length);
await rm(stateDir, { recursive: true, force: true });
process.exit(failed ? 1 : 0);
